entries[249469] = { ["name"] = "Frozen Heart of the Mountain", ["text"] = "Frozen Heart of the Mountain\nBinds when picked up\nUnique-Equipped\nTrinket\n+7 Fire Resistance\n+7 Nature Resistance\n+7 Frost Resistance\n+7 Shadow Resistance\nRequires Level 50\nEquip: Improves your chance to hit by 0.9%.\n\nUse: Increases Frost and Shadow spell damage done by up to 29 for 15 sec. This effect is doubled in Snowy areas. (5 Min Cooldown)\nSell Price:" }
entries[249470] = { ["name"] = "Molten Heart of the Mountain", ["text"] = "Molten Heart of the Mountain\nBinds when picked up\nUnique-Equipped\nTrinket\n+7 Fire Resistance\n+7 Nature Resistance\n+7 Frost Resistance\n+7 Shadow Resistance\nRequires Level 50\nEquip: + 2 Weapon Damage.\n\nUse: Increases Attack Power by 55 for 15 sec. This effect is doubled in Volcanic areas. (5 Min Cooldown)\nSell Price:" }
entries[249473] = { ["name"] = "Dormant Heart of the Mountain", ["text"] = "Dormant Heart of the Mountain\nBinds when picked up\nUnique-Equipped\nTrinket\n+7 Fire Resistance\n+7 Nature Resistance\n+7 Frost Resistance\n+7 Shadow Resistance\nRequires Level 50\nEquip: Your casts of Greater Heal, Healing Touch, Healing Wave, or Holy Light in combat grant up to 40 increased healing and up to 13 increased damage for 15 sec.\nSell Price:" }
entries[249474] = { ["name"] = "Formula: Enchant Bracer - Minor Intellect", ["text"] = "Binds when picked up\nRequires Enchanting (70)\n\nPermanently enchant bracers to give +3 Intellect.\n\"Teaches you how to permanently enchant bracers to give +3 Intellect.\"\nSell Price:" }
entries[249475] = { ["name"] = "Formula: Enchant Bracer - Minor Healing Power", ["text"] = "Binds when picked up\nRequires Enchanting (90)\n\nPermanently enchant bracers so they increase the wearer's healing spells by up to 8 and damage spells by up to 3.\n\"Teaches you how to permanently enchant bracers to increase Healing Power by up to 8 and Spell Damage by up to 3.\"\nSell Price:" }
