entries[249479] = { ["name"] = "Formula: Enchant Weapon - Insight", ["text"] = "Binds when picked up\nRequires Enchanting (140)\n\nPermanently enchant a Melee Weapon to have a chance to grant Insight when you cast a spell, increasing Spirit by 100% for 10 sec.\n\"Teaches you how to permanently enchant a weapon to grant a chance to gain Insight when you cast a spell, which gives +5% Spirit for a short duration.\"\nSell Price:" }
entries[249480] = { ["name"] = "Formula: Enchant Weapon - Recovery", ["text"] = "Binds when picked up\nRequires Enchanting (140)\n\nPermanently enchant a Melee Weapon to trigger Recovery when you are Parried or Dodged, healing you for 5% of your maximum health. Cannot occur more often than once every 10 sec.\n\"Teaches you how to permanently enchant a weapon to grant a chance to trigger Recovery when your attacks are dodged or parried, which heals you for 5% of your maximum health. Cannot occur more than once every 10 sec.\"\nSell Price:" }
entries[249481] = { ["name"] = "Formula: Enchant Weapon - Revelation", ["text"] = "Binds when picked up\nRequires Enchanting (140)\n\nPermanently enchant a Melee Weapon to have a chance to trigger Revelation when a non-periodic spell fails to critically strike. Revelation grants 100% increased critical strike chance to the next non-periodic spell cast. Revelation's chance to trigger is diminished as your critical strike chance increases.\n\"Teaches you how to permanently enchant a weapon to grant a chance to trigger Revelation when your direct spells fail to deal a critical strike. Revelation grants 100% increased critical strike chance to your next spell cast.\"\nSell Price:" }
